                        PasswordStrengthIndicator {
                            strength: password_strength.read().clone(),
                        }

                        Input {
                            label: "Confirm Password",
                            input_type: "password",
                            value: confirm_password.read().clone(),
                            onchange: move |val| confirm_password.set(val),
                            placeholder: "Re-enter password",
