use dioxus::prelude::*;
use api::login_user;

#[component]
pub fn LoginForm() -> Element {
    let mut username = use_signal(|| String::new());
    let mut password = use_signal(|| String::new());
    let mut remember_me = use_signal(|| false);
    let mut error_message = use_signal(|| None::<String>);
    let mut is_loading = use_signal(|| false);

    let handle_login = move |_| {
        spawn(async move {
            is_loading.set(true);
            error_message.set(None);

            match login_user(
                username.read().clone(),
                password.read().clone(),
            ).await {
                Ok(session) => {
                    // Store session
                    if remember_me.read().clone() {
                        // Store in localStorage
                        store_session(&session.session_id, 30); // 30 days
                    } else {
                        // Store in sessionStorage
                        store_session(&session.session_id, 0); // Session only
                    }

                    // Navigate based on user role
                    if session.user_role == UserRole::Provider {
                        navigator.push("/provider/dashboard");
                    } else {
                        navigator.push("/dashboard");
                    }
                }
                Err(e) => {
                    error_message.set(Some("Invalid username or password".to_string()));
                    is_loading.set(false);
                }
            }
        });
    };

    rsx! {
        div { class: "login-container",
