use dioxus::prelude::*;
use api::{get_current_user, logout_user, User, UserRole};
use std::rc::Rc;

#[derive(Clone, PartialEq)]
pub struct AuthState {
    pub user: Option<User>,
    pub session_id: Option<String>,
    pub is_loading: bool,
    pub is_authenticated: bool,
}

impl Default for AuthState {
    fn default() -> Self {
        Self {
            user: None,
            session_id: None,
            is_loading: true,
            is_authenticated: false,
        }
    }
}

pub struct AuthContext {
    pub state: Signal<AuthState>,
}

impl AuthContext {
    pub fn new() -> Self {
        Self {
            state: Signal::new(AuthState::default()),
        }
    }

    /// Initialize auth state from stored session
    pub async fn init(&mut self) {
        self.state.write().is_loading = true;

        // Try to get session from storage
        if let Some(session_id) = get_stored_session() {
            // Validate session with server
            match get_current_user(session_id.clone()).await {
                Ok(user) => {
                    self.state.write().user = Some(user);
                    self.state.write().session_id = Some(session_id);
                    self.state.write().is_authenticated = true;
                }
                Err(_) => {
                    // Session invalid, clear storage
                    clear_stored_session();
                }
            }
        }

        self.state.write().is_loading = false;
    }

    /// Login with session ID
    pub fn login(&mut self, session_id: String, user: User) {
        store_session(&session_id, 7); // 7 days
        self.state.write().session_id = Some(session_id);
        self.state.write().user = Some(user);
        self.state.write().is_authenticated = true;
    }

    /// Logout
    pub async fn logout(&mut self) {
        if let Some(session_id) = &self.state.read().session_id {
            let _ = logout_user(session_id.clone()).await;
        }

        clear_stored_session();
        self.state.write().user = None;
        self.state.write().session_id = None;
        self.state.write().is_authenticated = false;
    }

    /// Get current session ID (for server function calls)
    pub fn session_id(&self) -> Option<String> {
        self.state.read().session_id.clone()
    }

    /// Get current user
    pub fn user(&self) -> Option<User> {
        self.state.read().user.clone()
    }

    /// Check if user is a provider
    pub fn is_provider(&self) -> bool {
        self.state.read()
            .user
            .as_ref()
            .map(|u| u.role == UserRole::Provider)
            .unwrap_or(false)
    }
}

// Session storage utilities
#[cfg(target_arch = "wasm32")]
fn store_session(session_id: &str, days: i64) {
    use web_sys::window;
    if let Some(window) = window() {
        if let Ok(Some(storage)) = window.local_storage() {
            let _ = storage.set_item("session_id", session_id);
            let expiry = js_sys::Date::now() + (days as f64 * 24.0 * 60.0 * 60.0 * 1000.0);
            let _ = storage.set_item("session_expiry", &expiry.to_string());
        }
    }
}

#[cfg(target_arch = "wasm32")]
fn get_stored_session() -> Option<String> {
    use web_sys::window;
    if let Some(window) = window() {
        if let Ok(Some(storage)) = window.local_storage() {
            if let Ok(Some(expiry_str)) = storage.get_item("session_expiry") {
                if let Ok(expiry) = expiry_str.parse::<f64>() {
                    if js_sys::Date::now() < expiry {
                        return storage.get_item("session_id").ok().flatten();
                    }
                }
            }
        }
    }
    None
}

#[cfg(target_arch = "wasm32")]
fn clear_stored_session() {
    use web_sys::window;
    if let Some(window) = window() {
        if let Ok(Some(storage)) = window.local_storage() {
            let _ = storage.remove_item("session_id");
            let _ = storage.remove_item("session_expiry");
        }
    }
}

// Non-WASM stubs (for server-side rendering)
#[cfg(not(target_arch = "wasm32"))]
fn store_session(_session_id: &str, _days: i64) {}

#[cfg(not(target_arch = "wasm32"))]
fn get_stored_session() -> Option<String> { None }

#[cfg(not(target_arch = "wasm32"))]
fn clear_stored_session() {}
