use dioxus::prelude::*;
use crate::context::auth::{AuthContext, use_auth};

#[component]
pub fn ProtectedRoute(
    children: Element,
    #[props(default = false)] provider_only: bool,
) -> Element {
    let auth = use_context::<AuthContext>();
    let auth_state = auth.state.read();

    if auth_state.is_loading {
        return rsx! {
            div { class: "loading-screen",
                Spinner { size: SpinnerSize::Large }
                p { "Loading..." }
            }
        };
    }

    if !auth_state.is_authenticated {
        // Redirect to login
        use_effect(move || {
            navigator.push("/login");
        });
        return rsx! { div {} };
    }

    if provider_only && !auth.is_provider() {
        // Redirect to individual dashboard
        use_effect(move || {
            navigator.push("/dashboard");
        });
        return rsx! { div {} };
    }

    rsx! { {children} }
}
