fn calculate_avg_trend(patients: &[Patient]) -> String {
    if patients.is_empty() {
        return "N/A".to_string();
    }

    let total: f64 = patients.iter()
        .filter_map(|p| p.avg_mood)
        .sum();

    let avg = total / patients.len() as f64;
    format!("{:.1}", avg)
}

fn count_active_today(patients: &[Patient]) -> usize {
    let today = Local::now().date_naive();
    patients.iter()
        .filter(|p| {
            if let Ok(dt) = p.last_check_in.parse::<DateTime<Local>>() {
                dt.date_naive() == today
            } else {
                false
            }
        })
        .count()
}
